node Item {
    has name: str, enabled: bool = True;
}

{{solution}}

with entry {
    empty = root spawn CollectEnabled();
    assert empty.reports == [[]], "empty traversal must report once";
    bridge = Item(name="bridge", enabled=False);
    leaf = Item(name="leaf");
    side = Item(name="side");
    _detached = Item(name="detached");
    root ++> bridge;
    bridge ++> leaf;
    root ++> side;
    first = root spawn CollectEnabled();
    assert first.reports == [["leaf", "side"]], "traverse through disabled nodes, exclude detached nodes";
    again = root spawn CollectEnabled();
    assert again.reports == [["leaf", "side"]], "each spawn must have independent state";
    assert not bridge.enabled;
    assert leaf.name == "leaf" and side.name == "side";
    print("JACBRAIN_PASS_WALKER");
}

