with entry {
    first = InvoiceLine(sku="A", unit_price=7);
    second = InvoiceLine(sku="B", unit_price=5, quantity=3, tags=["bulk"]);
    third = InvoiceLine(sku="C", unit_price=11, quantity=0);
    assert first.sku == "A" and first.unit_price == 7;
    assert first.quantity == 1 and first.subtotal == 7;
    assert second.quantity == 3 and second.subtotal == 15;
    assert third.subtotal == 0;
    assert first.tags == [] and third.tags == [];
    first.tags.append("sale");
    assert second.tags == ["bulk"] and third.tags == [], "list defaults must not leak between instances";
    print("JACBRAIN_PASS_FIELDS");
}

