with entry {
    scores: dict[str, int] = {"z": 4, "a": 4, "m": -2, "b": 9};
    assert rank_scores(scores, 0) == ["b", "a", "z"];
    assert rank_scores(scores, 4) == ["b", "a", "z"], "threshold is inclusive";
    assert rank_scores(scores, 10) == [];
    assert rank_scores(scores, -2) == ["b", "a", "z", "m"];
    assert rank_scores({}, 0) == [];
    assert scores == {"z": 4, "a": 4, "m": -2, "b": 9}, "input must be unchanged";
    assert rank_scores({"beta": -3, "alpha": -3, "top": 0}, -3) == ["top", "alpha", "beta"];
    print("JACBRAIN_PASS_LAMBDA");
}

import from date_math { days_between }

with entry {
    assert days_between("2024-02-28", "2024-03-01") == 2;
    assert days_between("2025-02-28", "2025-03-01") == 1;
    assert days_between("2025-01-02", "2025-01-01") == -1;
    assert days_between("2025-06-01", "2025-06-01") == 0;
    rejected = False;
    try { _ = days_between("2025-02-30", "2025-03-01"); }
    except ValueError { rejected = True; }
    assert rejected, "invalid dates must preserve ValueError";
    print("JACBRAIN_PASS_IMPORTS");
}
